import{_ as c,l as d,o as e,c as s,v as o,p as i,x as t,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"栈、堆与静态存储","description":"","frontmatter":{"title":"栈、堆与静态存储","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stack-heap-static.md","filePath":"cs/stack-heap-static.md","lastUpdated":1789023840000}'),h={name:"cs/stack-heap-static.md"};function m(E,a,A,B,_,u){const r=d("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="栈、堆与静态存储" tabindex="-1">栈、堆与静态存储 <a class="header-anchor" href="#栈、堆与静态存储" aria-label="Permalink to &quot;栈、堆与静态存储&quot;">​</a></h1><div class="epigraph"><p>自动变量随调用生灭；静态与全局贯穿进程寿命；堆上的块由申请与释放配对，寿命不跟任何花括号走。</p><footer>—— 据 Kernighan &amp; Ritchie, The C Programming Language, 2nd ed.；Bryant and O&#39;Hallaron, Computer Systems: A Programmer&#39;s Perspective 整理</footer></div><p>上一课<a href="/cs/compile-link-entry">编译、链接与入口</a>把源到镜像的流水线钉死：加载之后从入口进 <code>main</code>。本课不重讲符号解析，也不从页表另起。缺口是：镜像进了进程，<strong>同名「变量」为何有的随函数返回消失、有的活到进程结束</strong>？三种存储期各对应哪片地址习惯，谁负责回收。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>函数里的局部变量通常在栈上：调用时分配一帧，返回时帧弹出，那片地址可被下次调用复用。文件作用域的对象与 <code>static</code> 局部在数据段（含 <code>.data</code> 与 <code>.bss</code>），链接时已定址，进程结束前一直有效。<code>malloc</code> 得到的块在堆上，寿命与指针绑定，直到 <code>free</code> 或泄漏。缺口因此不是关键字清单，而是<strong>寿命与地址区域的对应</strong>——后课的悬挂、栈溢出、别名都建立在这张图上。</p><p>把三种区域当成「编译器随便放」会写错所有权：返回局部数组的地址、把全局当临时缓冲、把堆指针当栈指针用，后课会一律落成未定义行为，但根子在本课没分清谁活多久。</p><h3 id="栈不是「比较快的数组」" tabindex="-1">栈不是「比较快的数组」 <a class="header-anchor" href="#栈不是「比较快的数组」" aria-label="Permalink to &quot;栈不是「比较快的数组」&quot;">​</a></h3><p>栈帧大小在进入函数时大体定好，不能当成任意增长的缓冲。把大对象或递归深度无界的工作丢进自动存储，碰到的是栈上限，不是堆的 <code>ENOMEM</code>。堆也不是无限：碎片与失败是运行时问题。本课只认区域分工，分配器内部结构交给后课。</p><p><span class="marginnote">K&amp;R 用 storage duration 同时描述可见性与寿命。CSAPP 把栈向下、堆向上画成程序员可用的地址空间草图；精确边界由操作系统与链接脚本定，<a href="/cs/process-addrspace-tour">进程地址空间一览</a>再收一次。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>自动存储：进栈帧，寿命是块作用域。静态存储：数据段，零初始化进 <code>.bss</code>，显式初值进 <code>.data</code>。动态存储：<code>malloc</code>/<code>free</code> 在堆区切块。线程局部静态是后课线程模型的缺口；本课默认单线程，三种区域已够用。</p>',11)),(e(),i(p,null,{default:t(()=>[n(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROC%5B%22%E8%BF%9B%E7%A8%8B%E5%9C%B0%E5%9D%80%E7%A9%BA%E9%97%B4%22%5D%20--%3E%20TEXT%5B%22%E4%BB%A3%E7%A0%81%E6%AE%B5%22%5D%0A%20%20PROC%20--%3E%20DATA%5B%22%E9%9D%99%E6%80%81%E4%B8%8E%E5%85%A8%E5%B1%80%22%5D%0A%20%20PROC%20--%3E%20HEAP%5B%22%E5%A0%86%EF%BC%9A%E9%9A%8F%20malloc%20%E4%BC%B8%22%5D%0A%20%20PROC%20--%3E%20STACK%5B%22%E6%A0%88%EF%BC%9A%E9%9A%8F%E8%B0%83%E7%94%A8%E4%BC%B8%22%5D%0A%20%20CALL%5B%22%E5%87%BD%E6%95%B0%E8%B0%83%E7%94%A8%22%5D%20--%3E%20STACK%0A%20%20MALLOC%5B%22malloc%22%5D%20--%3E%20HEAP%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>常见用户空间布局里栈与堆相向增长，中间留出扩展空隙。这是直觉，不是 ABI 保证。重要的是：返回之后栈上的对象结束寿命；堆上的块除非释放，否则一直占着，即使指针变量本身已经离开作用域。</p><p>线程局部存储是第四种常见区域，本课刻意不引入：默认单线程里，静态对象的共享已经够说明「不是每次调用一份」。堆与栈的相向增长在 64 位宽地址上很少撞上，但各自上限仍独立存在（<code>ulimit</code>、映射大小）。<code>alloca</code> 或变长数组在栈上动态伸一截，失败模式仍是栈而不是 <code>NULL</code>。后课指针会指向这三区中的对象；区域搞错时，别名与寿命分析会从错误的假设出发。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每次调用压栈：返回地址、保存的寄存器、局部与临时量。递归每深一层多一帧，深度受栈上限约束。堆分配可能触发系统调用抬高堆顶；释放后块可再分配给别人，<strong>同一地址稍后可能属于另一个对象</strong>——这是<a href="/cs/pointer-alias">指针与别名</a>与悬挂的共同土壤。</p><p>静态对象在 <code>main</code> 之前已完成初始化（C 保证），因此可以在任何函数里当稳定锚点。它们也因此不能表达「这次调用私有」的状态；那是栈的职责。三种区域不是性能技巧，是寿命的三种答案。</p><p>三种存储期一旦钉死，所有权问题才有落点：栈对象不能交给返回之后的调用方；堆对象必须在某个函数契约里写明谁 <code>free</code>；静态对象则对所有调用同时可见，因此不能表达「这一次调用私有」的缓冲。后课指针只是给这些区域里的对象起第二个名字，并不创造第四种寿命。把 <code>static</code> 局部当成「栈上但活得久」，会在递归里共享同一份存储，帧图立刻说不通。CSAPP 的地址空间草图在此够用：精确的段排列可以变，寿命分类不变。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开分配器空闲链表，也不讲多线程各有栈。对齐与结构体里的洞是<a href="/cs/alignment-padding">对齐与填充</a>的缺口。后课默认：自动→栈，静态/全局→数据段，动态→堆且需显式或日后 <a href="/cs/raii">RAII</a> 管理寿命。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>栈随调用分配帧，返回即失效；堆由 <code>malloc</code>/<code>free</code> 管寿命；静态与全局活过整个进程。</li><li>常见布局里栈与堆相向增长；数据段在链接时定址。</li><li>混淆区域是悬挂与别名的根源，不是「写法风格」。</li><li>下一课用指针给这些区域里的对象起第二个名字。</li><li>出处：K&amp;R storage duration；CSAPP 对程序地址空间的程序员模型。</li></ul>',10))])}const C=c(h,[["render",m]]);export{P as __pageData,C as default};
